def move_mercury_3(apps, schema_editor):
    """chat.inceptionlabs.ai retired Mercury 2 and serves Mercury 3 only, so every
    saved reference moves up — and the @mention bot answers on Mercury 3."""
    BotConfig = apps.get_model('api', 'BotConfig')
    ArenaChatSession = apps.get_model('api', 'ArenaChatSession')
    BackgroundAgentSession = apps.get_model('api', 'BackgroundAgentSession')

    for cfg in BotConfig.objects.all():
        updates = {}
        if cfg.provider == 'inception' and cfg.model == 'mercury-2':
            updates['model'] = 'mercury-3'
        chain = cfg.fallback_chain or ''
        if 'mercury-2' in chain:
            try:
                entries = json.loads(chain)
            except (ValueError, TypeError):
                entries = None
            if isinstance(entries, list):
                changed = False
                for entry in entries:
                    if isinstance(entry, dict) and entry.get('provider') == 'inception' and entry.get('model') == 'mercury-2':
                        entry['model'] = 'mercury-3'
                        changed = True
                if changed:
                    updates['fallback_chain'] = json.dumps(entries)
        if updates:
            BotConfig.objects.filter(pk=cfg.pk).update(**updates)

    # Neby's @mention replies run on Mercury 3 now.
    BotConfig.objects.filter(bot_username__iexact='neby').update(provider='inception', model='mercury-3')

    ArenaChatSession.objects.filter(provider='inception', model_id='mercury-2').update(model_id='mercury-3')
    ArenaChatSession.objects.filter(provider='inception', model_code='mercury-2').update(model_code='mercury-3')
    ArenaChatSession.objects.filter(provider='inception', model_display_name='Mercury 2').update(model_display_name='Mercury 3')
    BackgroundAgentSession.objects.filter(llm_provider='inception', llm_model='mercury-2').update(llm_model='mercury-3')


